VA.introLine=function(S,p,P,mc){
var rng=S.rng,others=P.filter(function(q){return q!==p&&(!HK.Pos||HK.Pos.okSex(p,q));});
var c=others.length?others[rng.int(others.length)].name:'共演者';
var v={a:p.name,c:c},r=rng(),t;
var combo=VA.INTRO_COMBO[p.action.id+'_'+p.goal.id];
var say=VA.INTRO_SAY[p.persona]&&VA.INTRO_SAY[p.persona][p.goal.id];
if(combo&&r<0.4)t=ST.fmt(ST.pick(S,combo),v);
else if(say&&r<0.75)t=p.name+ST.fmt(ST.pick(S,say),v)+(VA.INTRO_GOAL&&rng()<0.4?p.name+'は'+ST.pick(S,VA.INTRO_GOAL[p.goal.id].filter(function(x){return x.indexOf('「')<0;})):'');
else t=p.name+'は'+ST.pick(S,VA.INTRO_ACT[p.action.id])+ST.pick(S,VA.INTRO_GOAL[p.goal.id]);
if(mc&&rng()<0.35)t+='――'+mc+ST.pick(S,VA.INTRO_MC[p.goal.id]);
return t;
};
